   136	  });
   137	  
   138	  // For each day, group events by title
   139	  Object.keys(dayGroups).forEach(date => {
   140	    const dayEvents = dayGroups[date];
   141	    const titleGroups = {};
   142	    
   143	    dayEvents.forEach(event => {
   144	      const title = event.title || '';
